// Classification of .env keys and section behavior. Section behavior comes from
// marker suffixes in .env.example titles (e.g. "... - AUTOGENERATED ONCE IF
// VALUES ARE EMPTY"); key-pattern matching only picks the input widget and the
// rebuild-needed flag.

import type { Section, SectionItem } from './env-file';
import {
  AGENTS_OFF_LOCAL_LLM,
  AGENTS_OFF_PRIVACY,
  AGENTS_OFF_REPOSITORIES,
  OPENCLAW_OFF_CLAUDE,
  bothAgentsOff,
  type Component
} from './component-switches';

export type SectionMode = 'normal' | 'autogenerate' | 'hidden';

// Host ports published by the nginx proxy. Empty in .env.example, seeded on
// first setup (next free port if taken), then locked — services are configured
// against the initial ports, so changing them later would break the install.
export const SYSTEM_PORT_DEFAULTS: Record<string, string> = {
  SYSTEM_HTTP_PORT: '8888',
  SYSTEM_HTTPS_PORT: '8833'
};

export function isSystemPort(key: string): boolean {
  return key in SYSTEM_PORT_DEFAULTS;
}

// The page numbers what it shows, every section it shows. `.env.example` numbers its
// hidden sections too, so its numbers left a gap where section 4 is hidden (#51). The
// file keeps its own: privacy-proxy's contract test finds `# 7. PRIVACY PROXY` there
// by its exact text. Prose names a section by its title, so no number in it has to
// follow. A8-38.
export function numberShown<T extends { title: string }>(sections: T[]): T[] {
  return sections.map((s, i) => ({ ...s, title: `${i + 1}. ${s.title.replace(/^\d+\.\s+/, '')}` }));
}

export function sectionModeFromTitle(title: string): { mode: SectionMode; displayTitle: string } {
  let mode: SectionMode = 'normal';
  let marked = false;
  if (/AUTOGENERATED ONCE IF VALUES ARE EMPTY/i.test(title)) {
    mode = 'autogenerate';
    marked = true;
  } else if (/DO NOT SHOW UI/i.test(title)) {
    mode = 'hidden';
    marked = true;
  } else if (/USER CAN CHANGE ON FIRST RUN/i.test(title)) {
    marked = true;
  }
  const displayTitle = marked ? title.split(' - ')[0].trim() : title;
  return { mode, displayTitle };
}

// Changing any of these requires rebuilding images (IMAGE BUILD CONFIGURATION
// knobs consumed by build.sh, plus the OpenClaw build switch).
// A key whose change needs the stack built and started again before it takes effect: the save
// redirects with rebuild=1. PRIVACY_PROXY_ROUTING changes which providers, keys and logins the AI
// agents are given, which only a fresh start applies.
export function isBuildAffecting(key: string): boolean {
  return (
    key === 'ENABLE_ANTHROPIC_CLAUDE_CODE' ||
    key === 'PRIVACY_PROXY_ROUTING' ||
    /SYSTEM_DEPENDENCIES(_MODE)?$/.test(key) ||
    /POST_INSTALLATION_COMMANDS(_MODE)?$/.test(key)
  );
}

export function looksSecret(key: string): boolean {
  return /PASSWORD|SECRET|SECTET|_TOKEN$|_API_KEY$/.test(key);
}

export type InputType = 'text' | 'password' | 'number' | 'checkbox' | 'select-mode';

export function inputType(key: string, inlineComment = ''): InputType {
  // 0/1 flags — ENABLE_* provider toggles and *_ENABLE settings (e.g. the
  // PRIVACY_PROXY_* switches) — render as checkboxes.
  if (/^ENABLE_|_ENABLE$/.test(key)) return 'checkbox';
  // A key that declares its choices (see selectOptions) becomes a dropdown.
  if (selectOptions(key, inlineComment).length) return 'select-mode';
  if (/PORT$|TIMEOUT$/.test(key)) return 'number';
  if (looksSecret(key)) return 'password';
  return 'text';
}

// Dropdown choices for a field, taken from the key's inline
// `# a | b | c` comment in .env.example. The build-config *_MODE keys predate
// that notation, so they fall back to their add/override pair.
export function selectOptions(key: string, inlineComment = ''): string[] {
  const body = inlineComment.replace(/^#\s*/, '').trim();
  if (body.includes('|')) {
    const opts = body.split('|').map((o) => o.trim());
    if (opts.every((o) => /^[A-Za-z0-9_.-]+$/.test(o))) return opts;
  }
  return /_MODE$/.test(key) ? ['add', 'override'] : [];
}

// Sections rendered collapsed by default (matched against the full banner
// title); the autogenerate-marked section is collapsed independently.
export function isCollapsedSection(title: string): boolean {
  return false;
}

// Subheadings that fold the rest of their section into a nested collapsible.
export function isCollapsedSubheading(text: string): boolean {
  return /PER-IMAGE OVERRIDES|^ADVANCED\b/i.test(text);
}

// One-liners shown in a section header so a collapsed card still describes its
// contents. Keyword-matched against the full banner title (so renumbering
// sections doesn't break it); no entry falls back to the leading paragraph's
// first sentence.
const SECTION_DESCRIPTIONS: [RegExp, string][] = [
  [/WHICH APPS TO RUN/i, 'Liquid, OpenClaw and OpenCode — one that is switched off is not built or started.'],
  [/NETWORKING/i, "Host ports for the stack's web interfaces (<name>.localhost)."],
  [/AUTOGENERATED ONCE/i, 'Internal service passwords & tokens — generated automatically on save.'],
  [/USER CAN CHANGE ON FIRST RUN/i, 'Credentials you may want to set yourself before the first start.'],
  [/LLM PROVIDER API KEYS/i, 'API keys of LLM providers, used by the AI services (optional).'],
  [/OPENCLAW CONFIGURATION/i, 'Model & backend selection for OpenClaw, the recommended AI harness.'],
  [/OPENCODE CONFIGURATION/i, 'Self-hosted local LLM endpoint, shared by OpenCode and OpenClaw.'],
  [/PRIVACY PROXY/i, 'Privacy model for AI tools — connect to it like a local model; it cleans messages before the cloud AI sees them and restores the reply.'],
  [/LIQUID AUTHENTICATION/i, 'Login and TLS keystore credentials for Liquid.'],
  [/IMAGE BUILD CONFIGURATION/i, 'Extra packages & commands baked into the Docker images by build.sh.']
];

const SUBHEADING_DESCRIPTIONS: [RegExp, string][] = [
  [/PER-IMAGE OVERRIDES/i, 'Extend or replace the global build settings for a single image.'],
  [/^ADVANCED: SEPARATE JUDGE MODELS/i, 'Optional: other local models for the two privacy judgements.']
];

function firstSentence(text: string): string {
  const m = text.match(/^(.*?[.!?])(\s|$)/);
  return m ? m[1] : text.slice(0, 120);
}

export function sectionDescription(title: string, firstParagraph: string): string {
  for (const [re, desc] of SECTION_DESCRIPTIONS) if (re.test(title)) return desc;
  return firstParagraph ? firstSentence(firstParagraph) : '';
}

export function subheadingDescription(text: string, firstParagraph: string): string {
  for (const [re, desc] of SUBHEADING_DESCRIPTIONS) if (re.test(text)) return desc;
  return firstParagraph ? firstSentence(firstParagraph) : '';
}

// What has no reader while a component is switched off. The configuration view does not
// show it while that switch is off in the saved .env, and the save keeps its value (CS-FR12).
// Section 8 goes key by key: ENABLE_ANTHROPIC_CLAUDE_CODE is read by OpenCode and the
// privacy-proxy build too (decision 11). CS-19 pins the keys this yields over .env.example.
export const SECTION_DEPENDS_ON: [RegExp, Component][] = [[/LIQUID AUTHENTICATION/i, 'liquid']];
export const SUBHEADING_DEPENDS_ON: [RegExp, Component][] = [
  [/^Liquid$/i, 'liquid'],
  [/^OpenClaw$/i, 'openclaw'],
  [/^OpenCode$/i, 'opencode']
];
export const FIELD_DEPENDS_ON: Record<string, Component> = {
  ENABLE_GITHUB_COPILOT: 'openclaw',
  ENABLE_OPENAI_CODEX: 'openclaw',
  ENABLE_XAI_GROK: 'openclaw'
};

export function dependsOn(sectionTitle: string, subheading: string | null, key: string): Component | null {
  for (const [re, component] of SECTION_DEPENDS_ON) if (re.test(sectionTitle)) return component;
  if (subheading !== null) {
    for (const [re, component] of SUBHEADING_DEPENDS_ON) if (re.test(subheading)) return component;
  }
  return FIELD_DEPENDS_ON[key] ?? null;
}

/** Every field of the file that depends on a switch, with the subheading it sits under. */
export function dependentFields(sections: Section[]): Map<string, Component> {
  const found = new Map<string, Component>();
  for (const section of sections) {
    let subheading: string | null = null;
    for (const item of section.items) {
      if (item.kind === 'subheading') subheading = item.text;
      if (item.kind !== 'field') continue;
      const component = dependsOn(section.title, subheading, item.field.key);
      if (component) found.set(item.field.key, component);
    }
  }
  return found;
}

/**
 * A section's items as the view shows them. A subheading goes with its fields: one that
 * depends on a switch that is off goes, and so does one whose fields are all hidden, with
 * the paragraphs under it. A run without fields stays, so nothing shown today disappears.
 */
export function visibleItems(
  sectionTitle: string,
  items: SectionItem[],
  on: Record<Component, boolean>
): SectionItem[] {
  const off = (component: Component | null) => component !== null && !on[component];
  const runs: { head: SectionItem | null; items: SectionItem[] }[] = [{ head: null, items: [] }];
  for (const item of items) {
    if (item.kind === 'subheading') runs.push({ head: item, items: [] });
    else runs[runs.length - 1].items.push(item);
  }
  const shown: SectionItem[] = [];
  for (const run of runs) {
    const subheading = run.head?.kind === 'subheading' ? run.head.text : null;
    if (subheading !== null && off(dependsOn(sectionTitle, subheading, ''))) continue;
    const fields = run.items.filter((i) => i.kind === 'field');
    const kept = run.items.filter(
      (i) => i.kind !== 'field' || !off(dependsOn(sectionTitle, subheading, i.field.key))
    );
    if (fields.length > 0 && !kept.some((i) => i.kind === 'field')) continue;
    if (run.head) shown.push(run.head);
    shown.push(...kept);
  }
  return shown;
}

export function sectionNote(title: string, on: Record<Component, boolean>): string {
  if (!bothAgentsOff(on)) return '';
  if (/GIT INTEGRATION/i.test(title)) return AGENTS_OFF_REPOSITORIES;
  if (/PRIVACY PROXY/i.test(title)) return AGENTS_OFF_PRIVACY;
  if (/SELF-HOSTED LOCAL LLM/i.test(title)) return AGENTS_OFF_LOCAL_LLM;
  return '';
}

export function fieldNote(key: string, on: Record<Component, boolean>): string {
  return key === 'ENABLE_ANTHROPIC_CLAUDE_CODE' && !on.openclaw ? OPENCLAW_OFF_CLAUDE : '';
}
